import functools
def brute(n):
    full = (1 << 2 * n) - 1
    @functools.lru_cache(None)
    def go(mask):
        if mask == full: return 1
        cell = next(i for i in range(2 * n) if not mask >> i & 1); r, c = divmod(cell, 2); total = 0
        for w in range(1, 3 - c):
            for h in range(1, n - r + 1):
                block = sum(1 << (rr * 2 + cc) for rr in range(r, r + h) for cc in range(c, c + w))
                if mask & block: break
                total += go(mask | block)
        return total
    return go(0)
def shapes(n):
    wide = split = 1
    for _ in range(n - 1): wide, split = 2 * wide + split, wide + 4 * split
    return wide, split
result = brute(1)

